        foreach ($jadwalRaw as $namaKelas => $blocks) {
            $idKelas = $kelasMap[$namaKelas] ?? null;
            if (!$idKelas) continue;

            $i = 0;
            $n = count($blocks);
            $dayList = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat'];
            $dayIndex = 0;
            $jamKe = 1;

            while ($i < $n) {
                $item1 = $blocks[$i];
                if (in_array($item1, ['UPACA', 'RA', 'APEL', 'UPACARA', 'APEL', 'Pembia', 'saan', 'Hari', 'Jumat'])) {
                    $i++;
                    continue;
                }

                $mapel = $item1;
                $guruNama = null;
                $ruang = null;

                if ($i + 1 < $n) {
                    $guruNama = $blocks[$i + 1];
                }
                if ($i + 2 < $n && (str_starts_with($blocks[$i + 2], 'R ') || str_starts_with($blocks[$i + 2], 'Lab.') || $blocks[$i + 2] === 'LAP')) {
                    $ruang = $blocks[$i + 2];
                    $i += 3;
                } else {
                    $i += 2;
                }

                $idGuru = null;
                if ($guruNama) {
                    foreach ($guruMap as $gName => $gId) {
                        if (str_contains($gName, strtok($guruNama, ',')) || str_contains($guruNama, strtok($gName, ','))) {
                            $idGuru = $gId;
                            break;
                        }
                    }
                }

                $hari = $dayList[$dayIndex % 5];
                
                Jadwal::create([
                    'hari' => $hari,
                    'jam_ke' => $jamKe,
                    'id_kelas' => $idKelas,
                    'id_guru' => $idGuru,
                    'mapel' => $mapel,
                    'ruang' => $ruang,
                    'aktif' => 1,
                ]);

                $jamKe++;
                if ($jamKe > 10) {
                    $jamKe = 1;
                    $dayIndex++;
                }
            }
        }
    }
